  'consent_modal.pillar1_title': 'ಆ್ಯಪ್ ಸಕ್ರಿಯವಾಗಿದ್ದಾಗ ಮಾತ್ರ',
  'consent_modal.pillar1_desc': 'ನೀವು ಸಕ್ಷಮ್ ಬಳಸುವಾಗ ಮಾತ್ರ ಸ್ಥಳ ನವೀಕರಿಸಲಾಗುತ್ತದೆ. ಆ್ಯಪ್ ಮುಚ್ಚಿದಾಗ ನಾವು ಎಂದಿಗೂ ರಹಸ್ಯವಾಗಿ ಟ್ರ್ಯಾಕ್ ಮಾಡುವುದಿಲ್ಲ.',
  'consent_modal.pillar2_title': 'ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಎಂದಿಗೂ ಮಾರಾಟ ಅಥವಾ ಹಂಚಿಕೆ ಇಲ್ಲ',
  'consent_modal.pillar2_desc': 'ನಿಮ್ಮ ಸ್ಥಳವು ನಿಮ್ಮ ನಿಯೋಜಿತ ಪ್ರಾಥಮಿಕ ಆರೈಕೆದಾರರಿಗೆ ಮಾತ್ರ ಗೋಚರಿಸುತ್ತದೆ. ಜಾಹೀರಾತು ಟ್ರ್ಯಾಕಿಂಗ್ ಅಥವಾ ಡೇಟಾ ಬ್ರೋಕರ್‌ಗಳಿಲ್ಲ.',
  'consent_modal.pillar3_title': 'ಬ್ಯಾಟರಿ ಸ್ನೇಹಿ ಮತ್ತು ದೋಷ ಫಿಲ್ಟರ್ युक्त',
  'consent_modal.pillar3_desc': 'ಸ್ಮಾರ್ಟ್ GPS ಫಿಲ್ಟರ್ ಮನೆಯೊಳಗಿನ ತಪ್ಪು ಸಂಕೇತಗಳನ್ನು ನಿರ್ಲಕ್ಷಿಸಿ ಫೋನ್ ಬ್ಯಾಟರಿಯನ್ನು ಉಳಿಸುತ್ತದೆ.',
  'consent_modal.done': 'ಮುಗಿದಿದೆ ಮತ್ತು ಹಿಂತಿರುಗಿ',

  // Patient Cognitive Journal & Concern Modal
  'journal.title': 'ನಿಮ್ಮ ದೈನಂದಿನ ಟಿಪ್ಪಣಿಗಳು ಮತ್ತು ಅನುಭವ ಡೈರಿ',
  'journal.subtitle': 'ಏನು ಕಷ್ಟವೆನಿಸಿತು ಎಂಬುದನ್ನು ನಿಮ್ಮದೇ ಪದಗಳಲ್ಲಿ ದಾಖಲಿಸಲು ಒಂದು ಖಾಸಗಿ ಸ್ಥಳ.',
  'journal.share_btn': '+ ಕಷ್ಟವೆನಿಸಿದ್ದನ್ನು ಹಂಚಿಕೊಳ್ಳಿ',
  'journal.prepare_summary_btn': '📋 ವೈದ್ಯರ ಸಾರಾಂಶ ಸಿದ್ಧಪಡಿಸಿ',
  'journal.privacy_title': 'ನಿಮ್ಮ ಮಾತುಗಳು, ನಿಮ್ಮ ಗೌಪ್ಯತೆ:',
  'journal.privacy_desc': 'ಈ ಟಿಪ್ಪಣಿಗಳು ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಅನುಭವಗಳು. ವೈದ್ಯರ ಸಮಾಲೋಚನೆಯಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳಲು ಬಾಕ್ಸ್ ಗುರುತಿಸದ ಹೊರತು ಇವು ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಖಾಸಗಿಯಾಗಿರುತ್ತವೆ. ಇವುಗಳನ್ನು ಎಂದಿಗೂ ಕುಸಿತವೆಂದು ಅಳೆಯಲಾಗುವುದಿಲ್ಲ.',
  'journal.common_experiences_label': 'ಸಾಮಾನ್ಯ ಅನುಭವಗಳು (ಟಿಪ್ಪಣಿ ಮಾಡಲು ಟ್ಯಾಪ್ ಮಾಡಿ):',
  'journal.prompt_0': 'ನಾನು ಏನು ಮಾಡಲಿದ್ದೆ ಎಂಬುದನ್ನು ಮರೆತಿದ್ದೇನೆ.',
  'journal.prompt_1': 'ಒಂದು ವಸ್ತುವನ್ನು ಹುಡುಕಲು ನನಗೆ ಕಷ್ಟವಾಯಿತು.',
  'journal.prompt_2': 'ಪರಿಚಿತ ಸ್ಥಳದಲ್ಲಿ ನನಗೆ ಗೊಂದಲ ಅನಿಸಿತು.',
  'journal.prompt_3': 'ಪರಿಚಿತ ಕೆಲಸ ಮಾಡಲು ನನಗೆ ಹೆಚ್ಚಿನ ಸಹಾಯ ಬೇಕಾಯಿತು.',
  'journal.prompt_4': 'ಒಂದು ಸಂಭಾಷಣೆಯನ್ನು ನೆನಪಿಸಿಕೊಳ್ಳಲು ನನಗೆ ಕಷ್ಟವಾಯಿತು.',
  'journal.prompt_5': 'ನನಗೆ ತುಂಬಾ ಸುಸ್ತು ಅಥವಾ ಭಾರ ಅನಿಸಿತು.',
  'journal.prompt_6': 'ನನ್ನ ವೈದ್ಯರೊಂದಿಗೆ ಒಂದು ವಿಷಯದ ಬಗ್ಗೆ ಮಾತನಾಡಲು ಬಯಸುತ್ತೇನೆ.',
  'journal.recorded_notes_count': 'ನಿಮ್ಮ ದಾಖಲಾದ ಟಿಪ್ಪಣಿಗಳು ({count})',
  'journal.most_recent_first': 'ಇತ್ತೀಚಿನವು ಮೊದಲು',
  'journal.empty_title': 'ಇನ್ನೂ ಯಾವುದೇ ಡೈರಿ ನಮೂದುಗಳು ದಾಖಲಾಗಿಲ್ಲ.',
  'journal.empty_desc': 'ನೀವು ಅನುಭವವನ್ನು ದಾಖಲಿಸಲು ಬಯಸಿದಾಗಲೆಲ್ಲಾ ಮೇಲಿನ "+ ಕಷ್ಟವೆನಿಸಿದ್ದನ್ನು ಹಂಚಿಕೊಳ್ಳಿ" ಟ್ಯಾಪ್ ಮಾಡಿ.',
