  'loved_ones.reveal_relation_helper': 'ನೀವಿಬ್ಬರು ಹೇಗೆ ಸಂಬಂಧ ಹೊಂದಿದ್ದೀರಿ ಎಂಬುದನ್ನು ಮೃದುವಾಗಿ ನೆನಪಿಸಿಕೊಳ್ಳಲು ಯಾವಾಗ ಬೇಕಾದರೂ "ಸಂಬಂಧ ತೋರಿಸಿ" ಟ್ಯಾಪ್ ಮಾಡಿ. ಯಾವುದೇ ಒತ್ತಡ ಅಥವಾ ಪರೀಕ್ಷೆಯಿಲ್ಲ.',
